-- Migracion 111: limite geografico del municipio (poligono GeoJSON).
--
-- Clave `geo_limite_geojson` en configuracion_general: un GeoJSON Polygon
-- (coordenadas [lon, lat], WGS84) con el contorno del municipio. Lo usan:
--   * el mapa del inicio (GET /api/v1/dashboard/resumen -> geo.limite), que
--     sombrea con el naranja de ZARIS todo lo que queda FUERA del contorno y
--     encuadra el municipio entero (norte arriba);
--   * el generador de datos demo (services/demo_datos.py), que descarta los
--     puntos que caen fuera del contorno.
-- Deploy de otro municipio -> reemplazar el valor, no el codigo (mismo
-- criterio que geo_bbox_*, mig 87). Valor vacio o invalido = sin capa y sin
-- recorte (fail-closed: nada se rompe).
--
-- Valor sembrado: municipio demo "San Andres" = union de los partidos de
-- Vicente Lopez (OSM relation 2752665) y San Isidro (OSM relation 1769044),
-- simplificado a ~160 vertices (tolerancia 0.0002 grados, ~20 m).
-- Datos (c) colaboradores de OpenStreetMap, ODbL.
--
-- Solo datos (sin DDL). `tipo` y `activo` explicitos: prod los tiene NOT NULL
-- sin default (S21). ON CONFLICT DO NOTHING: no pisa un valor ajustado a mano.

INSERT INTO configuracion_general (clave, valor, tipo, descripcion, activo)
